pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }

    // General rule: After calling AdjustBetAmounts(amount) starting from initial betLimit==0,
    // the correct contract sets betLimit == amount. The mutant that does betLimit = betLimit + amount
    // will violate this for some amounts (it will make betLimit != amount when betLimit was not zero
    // or if repeated calls accumulate). We fuzz `amount` to find such a case.
    function testFuzz_property(uint256 amount) public {
        // keep domain wide but avoid extremely large values that could overflow internal expectations
        // (not strictly necessary here since Solidity 0.8 reverts on overflow and the reference uses direct assignment).
        // Ensure amount is within a practical range for the test harness.
        amount = bound(amount, 0, type(uint256).max);

        // At setUp, c was constructed with wagerLimit == 0, so initial betLimit == 0.
        // Call AdjustBetAmounts as the owner (deployer is owner in constructor).
        bool ok;
        try c.AdjustBetAmounts(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // The single assertion: in the correct contract (reference), the call should succeed
        // and c.currentBetLimit() should equal the passed amount. We assert that property.
        // This assertion is true for the reference for all amounts, but the mutant that
        // increments betLimit instead of setting it will make this equality fail for some amounts.
        assertTrue(ok && c.currentBetLimit() == amount);
    }
}

