pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }

    // Fuzz two amounts a and b. The general rule: after calling AdjustBetAmounts(a) then AdjustBetAmounts(b),
    // the reference contract (which assigns betLimit = amount) will have betLimit == b, whereas the mutant
    // that does betLimit = betLimit + amount will end with betLimit == a + b for some (a,b) and thus != b.
    function testFuzz_property(uint256 a, uint256 b) public {
        // keep domain wide but avoid trivial large overflows irrelevant to behavior (no need to bound tightly)
        // no vm.assume to ensure fuzzer can find counterexample

        // first call by owner (this) sets betLimit according to implementation
        // caller is contract deployer (owner) by setUp, so direct call is fine
        c.AdjustBetAmounts(a);
        c.AdjustBetAmounts(b);

        // Single assertion: reference contract guarantees betLimit equals the LAST parameter passed (b)
        // for all inputs; the mutant that accumulates will violate this for some (a,b) where a != 0.
        assertTrue(c.currentBetLimit() == b);
    }
}

