contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single test function driving the minimal sequence:
    // 1) owner opens to public and sets bet limit to `amount`
    // 2) caller wagers by sending exactly `amount`
    // The assertion: after these calls, hasPlayerWagered(caller) is true.
    // This holds for original (betLimit = amount) but breaks for mutant (betLimit = amount+1)
    function runTest(address whale, uint256 amount) public payable {
        // preconditions: caller must send exactly `amount` wei with this transaction
        require(msg.value == amount);

        // openToPublic and AdjustBetAmounts are owner-only in the real contract C.
        // We assume the test contract is the owner of C for this test setup.
        // Call AdjustBetAmounts(amount)
        c.AdjustBetAmounts(amount);

        // Allow public by calling OpenToThePublic
        c.OpenToThePublic();

        // Place the wager by forwarding the msg.value (amount)
        c.wager{value: msg.value}();

        // Observe that this caller has an active wager
        bool didWager = c.hasPlayerWagered(address(this));

        // The distinguishing assertion: must be true when betLimit == amount
        assert(didWager == true);
    }

    // allow receiving ETH for forwarding
    receive() external payable {}
}

