contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function performing the minimal sequence:
    // 1) record initial bet limit
    // 2) call AdjustBetAmounts with caller being this contract (which is neither owner nor whale)
    // 3) assert that only an owner (not whale) can change the bet limit by checking that when this contract is not owner, calling AdjustBetAmounts does not result in whale gaining ability to change bet limit. To trigger the distinguishing behavior we instead simulate: the test will require that when the contract caller is not owner, calling AdjustBetAmounts reverts (so betLimit stays the same). Under P this holds; under M (which allows whale) it may allow non-owner if the deployer is whale — but to keep within constraints, we assert that a non-owner call does not change the bet limit value.

    // The function takes a candidate newLimit and requires this contract is not owner by checking that calling OpenToThePublic (owner-only) reverts; this ensures msg.sender in this test is not owner. Then it attempts to call AdjustBetAmounts as this contract and finally asserts the bet limit is unchanged.

    function runTest(uint256 newLimit) public {
        // precondition: ensure this contract is not the owner by expecting OpenToThePublic to revert when called by this contract
        bool openReverted;
        try c.OpenToThePublic() {
            openReverted = false;
        } catch {
            openReverted = true;
        }
        require(openReverted, "test precondition: this contract must not be owner");

        // read initial bet limit
        uint256 before = c.currentBetLimit();

        // attempt to change bet limit as non-owner (this call should revert under original contract P,
        // or at least must not change the bet limit under P). We perform the call and ignore revert to allow asserting final value.
        // State-changing calls must be top-level statements.
        try c.AdjustBetAmounts(newLimit) {
            // succeeded
        } catch {
            // reverted
        }

        uint256 after = c.currentBetLimit();

        // Assert: when caller is not owner, bet limit must remain unchanged (holds in P, violated in mutant that allows extra principals)
        assert(after == before);
    }

    // receive to allow any refunds (not used but permitted)
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // caller will invoke run() from an EOA; we take two addresses as parameters
    // addrCaller: the msg.sender that will call this test (so AdjustBetAmounts is invoked by this EOA)
    // We also take a dummy uint256 newLimit to pass to AdjustBetAmounts.
    function run(address addrCaller, uint256 newLimit) public payable {
        require(addrCaller != address(0));
        // Ensure we call play first as in the provided sequence. play requires that
        // the contract is openToPublic and the caller has a wager; however, we cannot
        // guarantee those from here — but play is allowed to revert; the important
        // difference is whether AdjustBetAmounts reverts when called by a non-owner.
        // We therefore call play and ignore its potential revert by wrapping in try/catch.
        try c.play() {
            // no-op on success
        } catch {
            // ignore revert from play; proceed to AdjustBetAmounts test
        }

        bool reverted;
        // Call AdjustBetAmounts as the external caller (this function's msg.sender)
        // The test framework will call run with msg.sender set to addrCaller by using an EOA;
        // Solidity cannot change msg.sender within the contract, so we rely on the actual
        // test harness to invoke run from the chosen addrCaller. To ensure this, require
        // that the supplied addrCaller equals msg.sender — this forces the harness to call
        // run from the desired address.
        require(addrCaller == msg.sender);

        try c.AdjustBetAmounts(newLimit) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: if the caller is not the contract owner, AdjustBetAmounts must revert.
        // We cannot call c.owner() since owner is private, so express the rule purely in terms
        // of the caller: if the caller is not the owner, reverted must be true. Because we
        // cannot read owner, the only way to make this a general rule is to assert that any
        // caller different from the deployer of C (i.e., address(this) is not owner) must see revert.
        // To keep it general and observable, we assert: if this caller is not the same as the
        // contract's address that deployed C (i.e., msg.sender != address(c)), then AdjustBetAmounts reverts.
        // Note: address(c) is publicly observable.

        assert(!(msg.sender != address(c)) || reverted);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an address representing the caller who will invoke play() and then AdjustBetAmounts().
    // The test function is payable so the caller can send ETH to c if needed by wager/play flow in C.
    function run(address caller, uint256 newLimit) public payable {
        // Preconditions: caller must be an EOA (not a contract) and not the owner of c.
        // We cannot directly read owner from c (it's private), so require caller != address(this)
        // and rely on caller being tx.origin in order to simulate an EOA. We also ensure msg.sender
        // of this test is the same as caller by requiring tx.origin == caller. This narrows inputs
        // to cases where the external caller is an EOA executing this function.
        require(tx.origin == caller, "caller must be tx.origin (EOA)");

        // Call play() as the caller (this contract is acting on behalf of tx.origin==caller).
        // According to C, play() requires the player to be registered via wager() previously.
        // But to keep the precondition minimal while still exercising the branch difference we only
        // invoke play() — if preconditions in C are not met it will revert, which is allowed.
        // The important sequence is: play() then AdjustBetAmounts() by the same caller.
        try c.play{value: 0}() {
            // play call succeeded
        } catch {
            // play reverted — treat as completed step for establishing state (it may revert in both versions)
        }

        bool reverted;
        try c.AdjustBetAmounts(newLimit) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: For any EOA caller (tx.origin == caller) invoking play() then AdjustBetAmounts(...),
        // AdjustBetAmounts must revert (i.e., non-owner EOAs cannot successfully call it).
        assert(reverted == true);
    }

    receive() external payable {}
}

